/**
 * Cross-checks the Go edge's compact-SSE capture (edge/internal/capture/compact.go,
 * NewCompactCaptureForFormat) for the "response" (OpenAI Responses) and
 * "openai" (OpenAI Chat Completions) client formats: every TS settlement
 * parser that reads the upstream response body must produce an IDENTICAL
 * result when fed the compact text as when fed the full stream.
 *
 * The fixture (tests/fixtures/edge/capture/compact-formats.json) is
 * generated by the Go test edge/internal/capture/compact_formats_test.go
 * (run with UPDATE_FIXTURES=1) -- this file does not regenerate it, only
 * reads it.
 */
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, test } from "vitest";
import {
  hasStreamCompletionMarker,
  parseServiceTierFromResponseText,
  parseUsageFromResponseText,
} from "@/app/v1/_lib/proxy/response-handler";
import { extractActualResponseModelForProvider } from "@/app/v1/_lib/proxy/actual-response-model";
import { detectUpstreamErrorFromSseOrJsonText } from "@/lib/utils/upstream-error-detection";
import { isDiscoveryProtocolErrorPayload } from "@/app/v1/_lib/proxy/discovery-validity";
import { parseSSEData } from "@/lib/utils/sse";
import { SessionManager } from "@/lib/session-manager";

type FixtureCase = {
  name: string;
  format: "response" | "openai";
  providerType: string;
  full: string;
  compact: string;
};

const fixturePath = join(process.cwd(), "tests/fixtures/edge/capture/compact-formats.json");
const cases: FixtureCase[] = JSON.parse(readFileSync(fixturePath, "utf8"));

// Mirrors inspectStreamCompletion's isDiscoveryProtocolErrorPayload scan
// (response-handler.ts ~L1518) without needing the non-exported function.
function hasProtocolErrorPayload(text: string): boolean {
  return parseSSEData(text).some((event) => isDiscoveryProtocolErrorPayload(event.data));
}

// Mirrors the "response" branch of hasTerminalStreamUsageEvidence
// (response-handler.ts ~L1601-1611); the function itself is not exported,
// so this reimplements just enough to check full/compact parity for the
// "response" format cases this file covers.
function hasPositiveUsage(value: unknown): boolean {
  if (!value || typeof value !== "object") return false;
  const usage = value as Record<string, unknown>;
  const out = typeof usage.output_tokens === "number" ? usage.output_tokens : 0;
  return out > 0;
}

function hasTerminalUsageEvidenceResponse(text: string, hasMarker: boolean): boolean {
  if (!hasMarker) return false;
  return parseSSEData(text).some((event) => {
    if (!event.data || typeof event.data !== "object") return false;
    const data = event.data as Record<string, unknown>;
    const type = data.type;
    if (type !== "response.completed" && type !== "response.done") return false;
    const response =
      data.response && typeof data.response === "object"
        ? (data.response as Record<string, unknown>)
        : null;
    return hasPositiveUsage(data.usage) || hasPositiveUsage(response?.usage);
  });
}

function hasTerminalUsageEvidenceOpenAI(text: string, hasMarker: boolean): boolean {
  if (!hasMarker) return false;
  return parseSSEData(text).some((event) => {
    if (!event.data || typeof event.data !== "object") return false;
    const data = event.data as Record<string, unknown>;
    if (!hasPositiveUsage(data.usage)) return false;
    const choices = data.choices;
    if (Array.isArray(choices) && choices.length === 0) return true;
    return (
      Array.isArray(choices) &&
      choices.some(
        (choice) =>
          choice &&
          typeof choice === "object" &&
          typeof (choice as Record<string, unknown>).finish_reason === "string" &&
          (choice as Record<string, unknown>).finish_reason.toString().trim().length > 0
      )
    );
  });
}

describe("edge compact capture format parity (response / openai)", () => {
  test("fixture is present and non-empty", () => {
    expect(cases.length).toBeGreaterThan(0);
  });

  for (const c of cases) {
    describe(c.name, () => {
      test("parseUsageFromResponseText matches", () => {
        const full = parseUsageFromResponseText(c.full, c.providerType);
        const compact = parseUsageFromResponseText(c.compact, c.providerType);
        expect(compact.usageMetrics).toEqual(full.usageMetrics);
      });

      test("parseServiceTierFromResponseText matches", () => {
        const full = parseServiceTierFromResponseText(c.full);
        const compact = parseServiceTierFromResponseText(c.compact);
        expect(compact).toEqual(full);
      });

      test("extractActualResponseModelForProvider matches", () => {
        const isStream = !c.name.includes("non_sse");
        const full = extractActualResponseModelForProvider(
          c.providerType as never,
          isStream,
          c.full
        );
        const compact = extractActualResponseModelForProvider(
          c.providerType as never,
          isStream,
          c.compact
        );
        expect(compact).toEqual(full);
      });

      test("detectUpstreamErrorFromSseOrJsonText matches", () => {
        const full = detectUpstreamErrorFromSseOrJsonText(c.full);
        const compact = detectUpstreamErrorFromSseOrJsonText(c.compact);
        expect(compact.isError).toEqual(full.isError);
      });

      test("hasProtocolErrorPayload (isDiscoveryProtocolErrorPayload) matches", () => {
        const full = hasProtocolErrorPayload(c.full);
        const compact = hasProtocolErrorPayload(c.compact);
        expect(compact).toEqual(full);
      });

      test("hasStreamCompletionMarker matches", () => {
        const full = hasStreamCompletionMarker(c.full, c.format);
        const compact = hasStreamCompletionMarker(c.compact, c.format);
        expect(compact).toEqual(full);
      });

      test("terminal usage evidence matches", () => {
        const fullMarker = hasStreamCompletionMarker(c.full, c.format);
        const compactMarker = hasStreamCompletionMarker(c.compact, c.format);
        const evidenceFn =
          c.format === "response"
            ? hasTerminalUsageEvidenceResponse
            : hasTerminalUsageEvidenceOpenAI;
        const full = evidenceFn(c.full, fullMarker);
        const compact = evidenceFn(c.compact, compactMarker);
        expect(compact).toEqual(full);
      });

      if (c.format === "response") {
        test("SessionManager.extractCodexPromptCacheKey (first event with one) matches", () => {
          const extractFirst = (text: string): string | null => {
            for (const event of parseSSEData(text)) {
              if (!event.data || typeof event.data !== "object") continue;
              const key = SessionManager.extractCodexPromptCacheKey(
                event.data as Record<string, unknown>
              );
              if (key) return key;
            }
            return null;
          };
          const full = extractFirst(c.full);
          const compact = extractFirst(c.compact);
          expect(compact).toEqual(full);
        });
      }
    });
  }
});
